import numpy as np,json
from PIL import Image
cam='robot0_eye_in_hand'; im=np.array(Image.open('/app/output/move3/last/'+cam+'.jpg')); dep=np.load('/app/output/move3/depth_'+cam+'.npy')[0].astype(float); c=json.load(open('/app/output/move3/meta.json'))['cameras'][cam]; K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl'])
def world(u,v):
 z=dep[v,u]; p=np.array([(u-160)*z/K[0,0],-(v-120)*z/K[1,1],-z,1]);return (T@p)[:3]
for p in [(174,169),(160,150),(200,150),(210,170),(220,180),(140,150),(178,150),(178,185),(200,200),(220,210),(270,100)]:
 print(p,'rgb',im[p[1],p[0]],'d',dep[p[1],p[0]],'world',np.round(world(*p),3))
# stats world z among red tabletop pixels, spatial x 180..300 y100..210
xyz=[];rgb=[]
for v in range(100,210):
 for u in range(180,310):
  R,G,B=im[v,u]
  if R>100 and R>G*1.4 and R>B*1.3:
   xyz.append(world(u,v));rgb.append([R,G,B])
xyz=np.array(xyz)
print('red count',len(xyz),'z percentiles',np.percentile(xyz[:,2],[0,10,50,90,100]))
